<?php require_once __DIR__.'/includes/functions.php'; if(current_user()) redirect(role_home(current_user()['role'])); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $name=trim($_POST['name']??''); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $role='parent'; $password=$_POST['password']??''; if(!$name || !$email || strlen($password)<8){$error='Enter your name, a valid email, and a password of at least 8 characters.';} else {try{$stmt=db()->prepare('INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,'active']);  session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>$role];redirect('/parent/index.php');}catch(PDOException $ex){$error=$ex->getCode()==='23000'?'An account with this email already exists.':'Could not create account. Please check the database setup.';}}} $pageTitle='Create account'; require __DIR__.'/includes/header.php'; ?>
<section class="auth-layout"><div class="auth-aside"><span class="eyebrow">START YOUR CARE SPACE</span><h1>Make vaccination care<br><em>easier to follow.</em></h1><p>Build a clear record of appointments and vaccination milestones for your family.</p><div class="aside-stat"><span class="stat-icon">♡</span><span><b>Simple by design</b><small>Secure account-based access</small></span></div></div><form class="form-card" method="post"><h2>Create account</h2><p class="muted">Create a secure parent account to manage your family’s vaccination journey.</p><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Full name / hospital contact<input name="name" required maxlength="120" value="<?= e($_POST['name']??'') ?>" placeholder="Your name"></label><label>Email address<input type="email" name="email" required value="<?= e($_POST['email']??'') ?>" placeholder="you@example.com"></label><label>Password <small>(minimum 8 characters)</small><input type="password" name="password" minlength="8" required autocomplete="new-password" placeholder="Create a strong password"></label><button class="button primary full" type="submit">Create account →</button><p class="form-foot">Already registered? <a href="<?= BASE_URL ?>/login.php">Sign in</a></p></form></section><?php require __DIR__.'/includes/footer.php'; ?>
